insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('des-keawal-woa-a-scheaz-min-diitrich-woama-in-drei-minutn-drin', 'Des Keawal woa a Scheaz - min Diitrich woama in drei Minutn drin!', '', '', '', 'Wiener Gaunersprache', 'Das Körberl war ein Scherz - mit''m Dietrich waren wir in drei Minuten drinnen!', '[{"kategorie": "wörtlich", "text": "\"Das Vorhängeschlösschen war ein Scherz - mit''m Dietrich waren wir in drei Minuten drinnen!\"  2. Über das Vorhängeschloss konnten wir nur lachen – mit dem Dietrich war’s sofort offen!  3. Das Vorhängeschloss war ein Kinderspiel – drei Minuten und wir waren durch!"}]'::jsonb, ''),
  ('wos-offizioe-auf-da-rechnung-schdeed-is-nua-schoo-des-echte-keawalgoeoed-wiad-bar-untan-tisch-zoid', 'Wos offiziö auf da Rechnung schdeed, is nua Schoo - des echte Keawalgööd wiad bar untan Tisch zoid!', '', '', '', 'Wiener Gaunersprache', 'Was offiziell auf der Rechnung steht, ist nur Show – das echte Körberlgeld wird bar unter dem Tisch bezahlt!', '[{"kategorie": "wörtlich", "text": "\"Was auf der Rechnung steht, interessiert keinen – der echte [[Schmattes]] wird bar unter''m Tisch bezahlt!\"  2. Die Rechnung ist nur Tarnung – das Schwarzgeld fließt bar, diskret und ohne Beleg!  3. Die gedruckte Rechnung ist fürs Amt – das echte Geld wird unter der Hand, bar auf die Kralle, bezahlt!"}]'::jsonb, ''),
  ('ea-vadiint-si-a-klaans-keawalgoeoed-ois-nochhueuefeleara', 'Ea vadiint si a klaans Keawalgööd ois Nochhüüfeleara!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er verdient sich ein kleines Körberlgeld als Nachhilfelehrer!', '[{"kategorie": "wörtlich", "text": "\"Er verdient sich ein kleines Zubrot als Nachhilfelehrer!\"  2. Er hat einen kleinen Zusatzverdienst als Nachhilfelehrer!  3. Er erwirtschaftet ein bescheidenes Extrageld durch Nachhilfe!"}]'::jsonb, ''),
  ('si-a-klaans-kewalgoeoed-dazuavadiinan', 'si a klaans Kewalgööd dazuavadiinan', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich ein kleines Körberlgeld dazuverdienen', '[{"kategorie": "wörtlich", "text": "\"sich nebenbei ein kleines Zubrot verdienen\""}, {"kategorie": "", "text": "einen kleinen Zusatzverdienst einstreichen"}, {"kategorie": "", "text": "ein paar Groschen Extrageld dazuverdienen"}]'::jsonb, ''),
  ('si-de-heandln-oschdessn', 'si de Heandln oschdessn', '', '', '', '', 'sich die Hörner abstoßen', '[{"kategorie": "", "text": "durch die Schule des Lebens gehen"}, {"kategorie": "", "text": "Lehrgeld bezahlen müssen"}, {"kategorie": "", "text": "mit der Zeit Erfahrungen sammeln und reifer werden"}]'::jsonb, ''),
  ('wem-heandln-aufsetzn', 'wem Heandln aufsetzn', '', '', '', '', 'jemandem Hörner aufsetzen', '[{"kategorie": "", "text": "jemandem untreu sein"}, {"kategorie": "", "text": "jemanden hinterrücks betrügen"}, {"kategorie": "", "text": "jemanden nach Strich und Faden betrügen"}]'::jsonb, ''),
  ('keandln-lossn-miassn', 'Keandln lossn miassn', '', '', '', '', 'Körndeln lassen müssen', '[{"kategorie": "", "text": "an Ausdauer verlieren"}, {"kategorie": "", "text": "Kraftreserven einbüßen"}]'::jsonb, ''),
  ('keandlhockn', 'Keandlhockn', '', '', '', '', 'Körndelhacken', '[{"kategorie": "wörtlich", "text": "\"kraftraubende Arbeit\" (\"eine Arbeit, die viel Körner kostet\", Determinativkompositum aus [[Körndel]]=\"Körner\" und [[Hacken]]=\"Arbeit\")"}, {"kategorie": "allg.", "text": "Knochenarbeit, Schwerstarbeit, (Gaunersprache, wörtlich): \"Juwelenraub\" (Determinativkompositum aus [[Keandl]]=\"Juwelen\" und \"Hacken\"=\"Job\"), Juwelendiebstahl, Einbruchsdiebstahl (bei welchem Schmuck und Juwelen erbeutet werden)"}]'::jsonb, ''),
  ('wem-ind-kost-neema', 'wem ind Kost neema', '', '', '', '', 'jemanden in die Kost nehmen', '[{"kategorie": "", "text": "sich jemanden vorknöpfen, zur Brust nehmen  2. jemanden Ins Gebet nehmen, zur Rede stellen, [[si]] wem ausleichn"}]'::jsonb, ''),
  ('in-da-ruhe-liigd-de-kroft', 'In da Ruhe liigd de Kroft', '', '', '', '', 'In der Ruhe liegt die Kraft', '[{"kategorie": "wörtlich", "text": "\"In der Gelassenheit liegt die Stärke!\"  2. Mit Ruhe und Bedacht zum Erfolg!  3. Gut Ding braucht Weile!"}]'::jsonb, ''),
  ('im-kraas-gee', 'im Kraas gee', '', '', '', '', 'im Kreis gehen', '[{"kategorie": "", "text": "nicht vorwärts kommen"}, {"kategorie": "", "text": "trotz Bemühens keine Fortschritte erzielen"}, {"kategorie": "", "text": "auf der Stelle treten"}]'::jsonb, ''),
  ('si-im-kraas-draan', 'si im Kraas draan', '', '', '', '', 'sich im Kreis drehen', '[{"kategorie": "", "text": "nicht vorwärts kommen"}, {"kategorie": "", "text": "trotz Bemühens keine Fortschritte erzielen"}, {"kategorie": "", "text": "auf der Stelle treten"}]'::jsonb, ''),
  ('kraana-fressn-ollas-wos-eana-untan-schnoowae-kummd', 'Kraana fressn ollas, wos eana untan Schnoowä kummd!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Krähen fressen alles, was ihnen unter den Schnabel kommt!', '[{"kategorie": "wörtlich", "text": "\"Krähen picken alles auf, was ihnen vor den Schnabel fällt!\"  2. Krähen futtern einfach alles weg, was irgendwie essbar wirkt!  3. Krähen sind wahre Müllschlucker — die stopfen sich alles rein, als wären sie die Putztruppe der Natur!"}]'::jsonb, ''),
  ('de-kraana-im-park-schdoizian-umanaund-wia-klaane-schwoaze-gangstabosse', 'De Kraana im Park schdoizian umanaund wia klaane, schwoaze Gangstabosse!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Krähen im Park stolzieren herum wie kleine, schwarze Gangsterbosse!', '[{"kategorie": "wörtlich", "text": "\"Die Krähen im Park bewegen sich wie kleine, gefiederte Unterweltbosse durchs Gras!\"  2. Die Krähen führen sich auf wie Mini-Gangster, die den ganzen Park kontrollieren!  3. Die Krähen stolzieren da rum wie eine kleine, schwarze Mafia-Truppe!"}]'::jsonb, ''),
  ('des-kettal-hod-scheene-krallaln', 'Des Kettal hod scheene Krallaln!', '', '', '', '', 'Das Ketterl hat schöne Krallerln!', '[{"kategorie": "", "text": "Das Kettchen hat schöne Perlen aus Koralle!  2. Die Kette besteht aus hübschen Korallenperlen!  3. Die Halskette ist mit prächtigen Korallen verziert!"}]'::jsonb, ''),
  ('schiach-wia-da-krampus', 'schiach wia da Krampus', '', '', '', 'Wiener Sprüche, die sitzen!', 'schirch wie der Krampus', '[{"kategorie": "wörtlich", "text": "\"hässlich wie der Teufel\""}, {"kategorie": "", "text": "hässlich wie die Nacht"}, {"kategorie": "", "text": "zum Schreien hässlich"}]'::jsonb, ''),
  ('in-krampus-schbueuen', 'in Krampus schbüün', '', '', '', 'Wiener Sprüche, die sitzen!', 'den Krampus spielen', '[{"kategorie": "wörtlich", "text": "\"den bösen Mann spielen\""}, {"kategorie": "", "text": "den Bösewicht mimen"}, {"kategorie": "", "text": "den strengen Onkel geben"}]'::jsonb, ''),
  ('knecht-ruprecht', 'Knecht Ruprecht', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Knecht Ruprecht', '[{"kategorie": "wörtlich", "text": "\"Knecht Ruprecht\" (vom mittelhochdeutschen \"rûhperht\"=\"rauer Percht\")"}, {"kategorie": "allg.", "text": "\"höllisches Zottelwesen\" (Variante von [[Krampus]], vom mittelhochdeutschen \"krampe\"=\"Kralle\")"}, {"kategorie": "", "text": "Schreckgestalt (welche - nach altem Adventsbrauch - den Heiligen Nikolaus begleitet)"}]'::jsonb, 'Waunn da Knecht Ruprecht vua da Tia schdeed, vaschdeckst di schnöö untan Tisch!'),
  ('waunn-da-knecht-ruprecht-vua-da-tia-schdeed-vaschdeckst-di-schnoeoe-untan-tisch', 'Waunn da Knecht Ruprecht vua da Tia schdeed, vaschdeckst di schnöö untan Tisch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn der Knecht Ruprecht vor der Tür steht, versteckst du dich schnell unter dem Tisch!', '[{"kategorie": "wörtlich", "text": "\"Sobald Knecht Ruprecht klingelt, suchst du dir lieber ein Versteck unter dem Tisch!\"  2. Wenn Knecht Ruprecht ans Fenster klopft, flüchtest du sofort ins letzte Versteck!  3. Wenn das höllische Zottelwesen auftaucht, verschwindest du am besten unterm Esstisch!"}]'::jsonb, 'Knecht Ruprecht'),
  ('waunn-da-wuwu-vua-da-tia-schdeed-vaschdeckst-di-schnoeoe-untan-tisch', 'Waunn da Wuwu vua da Tia schdeed, vaschdeckst di schnöö untan Tisch!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Wenn der Wuwu vor der Tür steht, versteckst du dich schnell unter dem Tisch!', '[{"kategorie": "wörtlich", "text": "\"Sobald der Wuwu klingelt, suchst du dir lieber ein Versteck unter dem Tisch!\"  2. Wenn der Wuwu ans Fenster klopft, flüchtest du sofort ins letzte Versteck!  3. Wenn das höllische Zottelwesen auftaucht, verschwindest du am besten unterm Esstisch!"}]'::jsonb, ''),
  ('waunn-da-schdrooboat-vua-da-tia-schdeed-vaschdeckst-di-schnoeoe-untan-tisch', 'Waunn da Schdrooboat vua da Tia schdeed, vaschdeckst di schnöö untan Tisch!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Wenn der Strohbart vor der Tür steht, versteckst du dich schnell unter dem Tisch!', '[{"kategorie": "wörtlich", "text": "\"Sobald der Strohbart klingelt, suchst du dir lieber ein Versteck unter dem Tisch!\"  2. Wenn der Strohbart ans Fenster klopft, flüchtest du sofort ins letzte Versteck!  3. Wenn der Dämon mit Strohbart auftaucht, verschwindest du am besten unterm Esstisch!"}]'::jsonb, ''),
  ('waunn-da-rawuuzl-vua-da-tia-schdeed-vaschdeckst-di-schnoeoe-untan-tisch', 'Waunn da Rawuuzl vua da Tia schdeed, vaschdeckst di schnöö untan Tisch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn der Rawuzel vor der Tür steht, versteckst du dich schnell unter dem Tisch!', '[{"kategorie": "wörtlich", "text": "\"Sobald der Rawuzel klingelt, suchst du dir lieber ein Versteck unter dem Tisch!\"  2. Wenn der Rawuzel ans Fenster klopft, flüchtest du sofort ins letzte Versteck!  3. Wenn der Dämon in Koboldgestalt auftaucht, verschwindest du am besten unterm Esstisch!"}]'::jsonb, ''),
  ('waunn-da-raubutzl-vua-da-tia-schdeed-vaschdeckst-di-schnoeoe-untan-tisch', 'Waunn da Raubutzl vua da Tia schdeed, vaschdeckst di schnöö untan Tisch!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Wenn der Raubutzel vor der Tür steht, versteckst du dich schnell unter dem Tisch!', '[{"kategorie": "wörtlich", "text": "\"Sobald der Raubutzel klingelt, suchst du dir lieber ein Versteck unter dem Tisch!\"  2. Wenn der Raubutzel ans Fenster klopft, flüchtest du sofort ins letzte Versteck!  3. Wenn der Dämon in Koboldgestalt auftaucht, verschwindest du am besten unterm Esstisch!"}]'::jsonb, ''),
  ('waunns-ramsampal-vua-da-tia-schdeed-vaschdeckst-di-schnoeoe-untan-tisch', 'Waunns Ramsampal vua da Tia schdeed, vaschdeckst di schnöö untan Tisch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn das Ramsamperl vor der Tür steht, versteckst du dich schnell unter dem Tisch!', '[{"kategorie": "wörtlich", "text": "\"Sobald das Ramsamperl klingelt, suchst du dir lieber ein Versteck unter dem Tisch!\"  2. Wenn das Ramsamperl ans Fenster klopft, flüchtest du sofort ins letzte Versteck!  3. Wenn der Dämon in Koboldgestalt auftaucht, verschwindest du am besten unterm Esstisch!"}]'::jsonb, ''),
  ('si-hod-eam-in-de-krampaln', 'Si hod eam in de Krampaln!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Sie hat ihn in den Kramperln', '[{"kategorie": "wörtlich", "text": "Sie hält ihn fest in ihren Fängen!  2. Sie hält ihn fest und lässt ihn nicht mehr los!  3. Sie hat ihn fest in ihrer Gewalt!"}]'::jsonb, ''),
  ('i-moch-da-an-krampaltee-daunn-bist-muang-wiida-aufd-fiass', 'I moch da an Krampaltee, daunn bist muang wiida aufd Fiass!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Ich mach dir einen Kramperltee, dann bist du morgen wieder auf den Beinen!', '[{"kategorie": "wörtlich", "text": "\"Ich mach dir einen Kräutertee mit Isländisch Moos, dann bist du morgen wieder gesund!\"  2. Ein Schluck Isländisch-Moos-Tee und du bist morgen wie neu!  3. Ich koch dir einen Tee mit Isländisch Moos – das hilft dir sicher auf die Beine!"}]'::jsonb, ''),
  ('wo-picksd-ma-dein-rawuuzl-jetzt-hii', 'Wo picksd ma dein Rawuuzl jetzt hii?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wo pickst du mir deinen Rawuzel jetzt hin?', '[{"kategorie": "wörtlich", "text": "\"Wo klebst du mir deinen Nasenrammel jetzt hin?\"  2. Wohin entsorgst du deinen Nasenpopel jetzt bei mir?  3. Sag mal – wo willst du jetzt deinen [[Rammel]] bei mir abladen?"}]'::jsonb, ''),
  ('wo-picksd-ma-dein-raubutzl-jetzt-hii', 'Wo picksd ma dein Raubutzl jetzt hii?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wo pickst du mir deinen Raubutzel jetzt hin?', '[{"kategorie": "wörtlich", "text": "\"Wo klebst du mir deinen Nasenrammel jetzt hin?\"  2. Wohin entsorgst du deinen Nasenpopel jetzt bei mir?  3. Sag mal – wo willst du jetzt deinen [[Rammel]] bei mir abladen?"}]'::jsonb, ''),
  ('den-rawuuzl-muassd-easchd-duschn-schickn-bevuasd-eam-aum-tisch-lossn-kaunnst', 'Den Rawuuzl muassd easchd duschn schickn, bevuasd eam aum Tisch lossn kaunnst!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Diesen Rawuzel musst du erst duschen schicken, bevor du ihn an den Tisch lassen kannst!', '[{"kategorie": "wörtlich", "text": "\"Diesen Schmutzfink musst du erst duschen schicken, bevor du ihn an den Tisch lassen kannst!\"  2. Bevor dieser Dreckspatz an den Tisch darf, sollte er dringend mal unter die Dusche!  3. Dieser ungepflegte Kerl gehört erst mal gründlich gewaschen, bevor er mitessen darf!"}]'::jsonb, ''),
  ('a-schwoaza-rawuuzl', 'a schwoaza Rawuuzl', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein schwarzer Raubutzel', '[{"kategorie": "wörtlich", "text": "\"eine schwarze Schreckgestalt\" (Determinativkompositum aus \"raa\"=\"rau\" und \"Wutzel\"=\"Butzel\"[kleiner Kobold\"])"}, {"kategorie": "allg.", "text": "dunkelhäutiger Mann, (scherzhaft für): Schwarzafrikaner, Dunkelhäutiger, [[Murl]], [[Aubreenda]], [[Neger]]"}]'::jsonb, ''),
  ('des-is-a-kraumpf', 'Des is a Kraumpf!', '', '', '', '', 'Das ist ein Krampf!', '[{"kategorie": "", "text": "Das ist ein Ärgernis!  2. Das ist eine Nerverei!  3. Das ist eine Strapaze!"}]'::jsonb, ''),
  ('graal', 'Grààl', '', '', '', '', 'Kranl', '[{"kategorie": "wörtlich", "text": "\"Krönchen bzw. Kränzchen\" (vom mittelhochdeutschen \"kran\"=\"Krone\" bzw. \"Kranz\")"}, {"kategorie": "Kurzform für", "text": "\"österreichische [[Krone]]\" (amtliche Goldwährung in Österreich-Ungarn von 1892 bis 1918)"}, {"kategorie": "allg.", "text": "Münze, Goldmünze, Geldstück, Geld"}, {"kategorie": "", "text": "Krone (goldene und mit Edelsteinen versehene Kopfzierde von Herrschern als Zeichen deren Macht und Würde), Kopfschmuck, Kopfzierde, (zool.) Kopffeder von Vögeln"}]'::jsonb, ''),
  ('s-letzte-graal', 's letzte Grààl', '', '', '', '', 'das letzte Kranl', '[{"kategorie": "wörtlich", "text": "\"die letzte Krone\" (=Goldmünze)"}, {"kategorie": "", "text": "der letzte Groschen"}, {"kategorie": "", "text": "das allerletzte Geld"}]'::jsonb, ''),
  ('sei-letztes-graal-vaschbueuen', 'sei letztes Grààl vaschbüün', '', '', '', '', 'sein letztes Kranl verspielen', '[{"kategorie": "wörtlich", "text": "sein letztes Geld verspielen"}, {"kategorie": "", "text": "seinen letzten Notgroschen verzocken"}, {"kategorie": "", "text": "sein allerletztes Geld auf den Kopf hauen"}]'::jsonb, ''),
  ('de-kraenk-haum', 'de Kränk haum', '', '', '', '', 'das Kränkeln haben', '[{"kategorie": "wörtlich", "text": "\"einen krankheitsbedingten Durchhänger haben\""}, {"kategorie": "", "text": "nicht ganz auf der Höhe sein"}, {"kategorie": "", "text": "schlapp auf den Beinen sein"}, {"kategorie": "", "text": "eine depressive Verstimmung haben"}]'::jsonb, ''),
  ('an-kraunknsessl-dahaam-haum', 'an Kraunknsessl dahaam haum', '', '', '', '', 'einen Krankensessel daheim haben', '[{"kategorie": "", "text": "einen Dauerkranken bei sich zu Hause haben"}, {"kategorie": "", "text": "einen Pflegefall bei sich zu Hause haben"}, {"kategorie": "", "text": "einen pflegebedürftigen Angehörigen im Haus haben"}]'::jsonb, ''),
  ('a-greans-kranzal-winkt', 'A greans Kranzal winkt!', '', '', '', '', 'Ein grünes Kranzerl winkt!', '[{"kategorie": "wörtlich", "text": "\"Ein grünes Kränzchen winkt!\"  2. Ein Reisigkränzchen grüßt von der Heurigentüre! (und zeigt uns allen an, dass der Heurige heute geöffnet ist)"}]'::jsonb, ''),
  ('des-is-a-graeu-fia-mi', 'Des is a Gräu fia mi!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist ein Gräuel für mich!', '[{"kategorie": "wörtlich", "text": "\"Das ist mir ein Gräuel!\"  2. Das ist mir völlig zuwider!  3. Das ist mir echt ein Graus!  4. Ich kann das auf den Tod nicht ausstehen!"}]'::jsonb, ''),
  ('mit-iare-schoafn-kraeun-hods-eam-es-gaunze-gsichd-zakrotzd', 'Mit iare schoafn Kräun hods eam es gaunze Gsichd zakrotzd!', '', '', '', 'Wiener Gaunersprache', 'Mit ihren scharfen Kräueln hat sie ihm das ganze Gesicht zerkratzt!', '[{"kategorie": "wörtlich", "text": "\"Mit ihren scharfen Krallen hat sie ihm das ganze Gesicht zerkratzt!\"  2. Mit ihren scharfen Fingernägeln hat sie ihm das Gesicht aufgerissen!  3. Wie eine Raubkatze hat sie ihm das Gesicht mit ihren scharfen Krallen aufgeritzt!"}]'::jsonb, ''),
  ('nimm-in-kraeu-und-loackas-blumanbeedl-a-weng-auf', 'Nimm in Kräu und loackas Blumanbeedl a weng auf!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Nimm den Kräuel und lockere das Blumenbeet ein wenig auf!', '[{"kategorie": "wörtlich", "text": "\"Nimm die Gartenkralle und lockere damit das Blumenbeet ein wenig auf!\"  2. Hol dir die Kralle und geh mal kurz durchs Blumenbeet!  3. Mach das Beet mal locker mit der Kralle, sonst wächst da nix!"}]'::jsonb, ''),
  ('kraeu-ma-jetzt-den-beag-auffe-oda-ned', 'Kräu ma jetzt den Beag auffe oda ned?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Kräulen wir jetzt den Berg rauf oder nicht?', '[{"kategorie": "wörtlich", "text": "\"Klettern wir jetzt den Berg hoch oder nicht?\"  2. Schleppen wir uns jetzt den berg hoch oder sparen wir uns das?  3. Wagen wir den Aufstieg oder bleiben wir unten?"}]'::jsonb, ''),
  ('de-kotz-hod-mi-kraeud', 'De Kotz hod mi kräud!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Die Katze hat mich gekräult!', '[{"kategorie": "wörtlich", "text": "\"Die Katze hat mich gekratzt!\"  2. Die Katze hat mich mit ihren Krallen erwischt!  3. Die Katze hat mir eine Kratzwunde zugefügt!"}]'::jsonb, ''),
  ('wem-kraeun-lossn', 'wem kräun lossn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden kräulen lassen', '[{"kategorie": "wörtlich", "text": "\"jemanden kriechen lassen\""}, {"kategorie": "fig.", "text": "jemanden vorführen"}, {"kategorie": "", "text": "jemanden absichtlich zappeln lassen"}]'::jsonb, 'Si hod eam kräun lossn, bisa aum Schluss Schdaub gschlickd hod!'),
  ('si-hod-eam-kraeun-lossn-bisa-aum-schluss-schdaub-gschlickd-hod', 'Si hod eam kräun lossn, bisa aum Schluss Schdaub gschlickd hod!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie hat ihn kräulen lassen, bis er am Schluss Staub geschluckt hat!', '[{"kategorie": "wörtlich", "text": "\"Sie hat ihn kriechen lassen, bis er am Schluss Staub geschluckt hat!\"  2. Sie hat ihn zappeln lassen, bis er komplett am Ende war!  3. Sie hat ihn so lange kriechen lassen, bis er nur noch auf dem Boden lag!"}]'::jsonb, 'wem kräun lossn'),
  ('bsoffn-ins-bett-kraeun', 'bsoffn ins Bett kräun', '', '', '', 'Wiener Sprüche, die sitzen!', 'besoffen ins Bett kriechen', '[{"kategorie": "wörtlich", "text": "\"sich betrunken ins Bett schleppen\""}, {"kategorie": "", "text": "sturzbetrunken ins Bett krabbeln"}, {"kategorie": "", "text": "sternhagelvoll ins Bett klettern"}]'::jsonb, ''),
  ('wiari-gestan-bsoffn-ins-bett-kraeud-bin-woa-des-definitiv-da-schboadlichste-moment-von-mein-gaunzn-tag', 'Wiari gestan bsoffn ins Bett kräud bin, woa des definitiv da schboadlichste Moment von mein gaunzn Tag!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wie ich gestern besoffen ins Bett gekräult bin, war dies der definitiv sportlichste Moment von meinem ganzen Tag!', '[{"kategorie": "wörtlich", "text": "\"Als ich gestern besoffen ins Bett geklettert bin, war dies der definitiv sportlichste Moment meines ganzen Tages!\"  2. Als ich gestern betrunken ins Bett gekraxelt bin, war dies eine sportliche Höchstleistung!  3. Meine einzige sportliche Betätigung gestern war, dass ich sternhagelvoll ins Bett gekrabbelt bin!"}]'::jsonb, ''),
  ('kraeu-ma-in-buugl-owe', 'Kräu ma in Buugl owe!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Kräule mir den Buckel runter', '[{"kategorie": "wörtlich", "text": "\"Kriech mir den Buckel runter!\"  2. \"Rutsch mir den Buckel runter!\"  3. Kriech mir von der Pelle!  4. Mach dich vom Acker!  5. [[Schleich]] di!  6. [[Vazupf]] di!"}]'::jsonb, ''),
  ('wem-in-oasch-kraeun', 'wem in Oasch kräun', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem in den Arsch kräulen', '[{"kategorie": "wörtlich", "text": "\"jemandem in den Hintern kriechen\""}, {"kategorie": "", "text": "\"jemandem Zucker in den Hintern blasen\""}, {"kategorie": "", "text": "\"jemandem Honig ums Maul schmieren\""}, {"kategorie": "", "text": "\"jemandem nach dem Mund reden\""}, {"kategorie": "", "text": "\"jemandem in den Allerwertesten kriechen\""}]'::jsonb, 'Dea kräud in Schääf so tiaf in Oasch, dassa boid oisa Gaunza in sein Enddarm schdeckd!'),
  ('wueuesd-ma-in-oasch-kraeun-oda-suchast-nua-an-woaman-plotz-fian-winta', 'Wüüsd ma in Oasch kräun oda suchast nua an woaman Plotz fian Winta?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Willst du mir in den Arsch kräulen oder suchst du nur einen warmen Platz für den Winter?', '[{"kategorie": "wörtlich", "text": "\"Willst du mir in den Arsch kriechen oder suchst du nur einen warmen Platz für den Winter?\"  2. Bist du gerade am Schleimen oder brauchst du einfach nur etwas Körperwärme?  3. Kriechst du mir aus Überzeugung so tief in den Hintern – oder ist dir einfach nur kalt?"}]'::jsonb, 'wem in Oasch kräun'),
  ('wem-de-eia-schaukln', 'wem de Eia schaukln', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem die Eier schaukeln', '[{"kategorie": "wörtlich", "text": "\"jemandem in den Hintern kriechen\""}, {"kategorie": "", "text": "\"jemandem Zucker in den Hintern blasen\""}, {"kategorie": "", "text": "\"jemandem Honig ums Maul schmieren\""}, {"kategorie": "", "text": "\"jemandem nach dem Mund reden\""}, {"kategorie": "", "text": "\"jemandem in den Allerwertesten kriechen\""}]'::jsonb, 'wem von hint einekräun'),
  ('dea-schaukld-in-schaeaef-de-eia-bisa-befoeadad-wiad', 'Dea schaukld in Schääf de Eia, bisa beföadad wiad!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der schaukelt dem Chef die Eier, bis er befördert wird!', '[{"kategorie": "wörtlich", "text": "\"Der kriecht seinem Chef in den Arsch, bis er befördert wird!\"  2. \"Der bläst seinem Chef Zucker in den Hintern, bis er ihn auf einen besseren Postens setzt!  3. Der schmiert seinem Chef Honig ums Maul, bis er in die Führungsetage aufsteigt!"}]'::jsonb, 'wem de Eia schaukln'),
  ('hueuefe-do-kraeud-wos', 'Hüüfe, do kräud wos!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Hilfe, da kräult was!', '[{"kategorie": "wörtlich", "text": "\"Hilfe, da krabbelt was!\"  2. Hilfe, da kreucht und fleucht irgendwas!  3. Hilfe, da krabbelt irgend so ein Viech rum!"}]'::jsonb, ''),
  ('dea-kraeud-vom-preis-ned-owa', 'Dea kräud vom Preis ned owa!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der kräult vom Preis nicht runter!', '[{"kategorie": "wörtlich", "text": "\"Der steigt vom Preis nicht runter!\"  2. Er geht mit dem Preis nicht runter!  3. Er bewegt sich keinen Millimeter und bleibt hart bei seiner Preisforderung!"}]'::jsonb, ''),
  ('den-kraeula-im-gsichd-hob-i-von-mein-kooda', 'Den Kräula im Gsichd hob I von mein Kooda!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Den Kräuler im Gesicht hab ich von meinem Kater!', '[{"kategorie": "wörtlich", "text": "\"Den Kratzer im Gesicht hab ich von meinem Kater!\"  2. Der Kratzer im Gesicht stammt von meinem Kater!  3. Mein Stubentiger war schlecht gelaunt – daher der Kratzer!"}]'::jsonb, ''),
  ('in-unsara-firma-foisd-nua-auffe-waunnsd-a-talentiada-kraeula-bist', 'In unsara Firma foisd nua auffe, waunnsd a talentiada Kräula bist!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'In unserer Firma fällst du nur nach oben, wenn du ein talentierter Kräuler bist!', '[{"kategorie": "wörtlich", "text": "\"In unserer Firma wirst du nur befördert, wenn du ein talentierter Schleimer bist!\"  2. Bei uns in der Firma steigst nur auf, wenn du ein Meister im Arschkriechen bist!  3. Beförderungen in unserer Firma gibt''s hier nur für Spezialisten im Einschleimen!"}]'::jsonb, ''),
  ('da-kuatl-is-ka-tschlziaga-des-is-a-kraeula', 'Da Kuatl is ka Tschlziaga, des is a Kräula!', '', '', '', 'Wiener Gaunersprache', 'Der Kurtl ist kein Taschelzieher, das ist ein Kräuler!', '[{"kategorie": "wörtlich", "text": "\"Der Kurt ist kein Taschendieb, das ist ein Einschleichdieb!\"  2. Der Kurt klaut nicht auf der Straße, der schleicht sich in Wohnungen ein!  3. Der Kurt ist kein einfacher Taschendieb - er ist Wohnungseinbrecher und Profi im Einschleichen!"}]'::jsonb, ''),
  ('dea-graeula-fiad-si-auf-wia-de-letzte-sau', 'Dea Gräula fiad si auf wia de letzte Sau!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Dieser Gräuler führt sich auf wie die letzte Sau!', '[{"kategorie": "wörtlich", "text": "\"Dieser Widerling führt sich auf wie das letzte Schwein!\"  2. Dieses Scheusal benimmt sich wie das allerletzte Schwein!  3. Dieser widerliche Typ hat überhaupt keinen Anstand!"}]'::jsonb, ''),
  ('sei-kraeulade-oat-is-afoch-nua-eabaeamlich', 'Sei kräulade Oat is afoch nua eabäamlich!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Seine kräulerte Art ist einfach nur erbärmlich!', '[{"kategorie": "wörtlich", "text": "\"Seine kriecherische Art ist einfach nur erbärmlich!\"  2. Sein schleimiges Getue ist einfach nur zum Kotzen!  3. Sein anbiederndes Verhalten ist einfach beschämend!"}]'::jsonb, ''),
  ('wem-kraeulad-mochn', 'wem kräulad mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden kräullert machen', '[{"kategorie": "wörtlich", "text": "\"jemanden wütend machen\""}, {"kategorie": "", "text": "jemanden auf die Palme bringen"}, {"kategorie": "", "text": "jemanden in Rage versetzen"}]'::jsonb, 'Dea mochd mi so kräulad, dass I eam de Goschn eihaun kennt!'),
  ('dea-mochd-mi-so-kraeulad-dass-i-eam-de-goschn-eihaun-kennt', 'Dea mochd mi so kräulad, dass I eam de Goschn eihaun kennt!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Der macht mich so kräulert, dass ich ihm die Goschen einhauen könnt!', '[{"kategorie": "wörtlich", "text": "\"Der macht mich so wütend, dass ich ihm die Fresse polieren könnt!\"  2. Der regt mich so auf, ich könnt ihm direkt eine reinhauen!  3. Der treibt mich so auf die Palme, dass ich ihm am liebsten eine klatschen würd!"}]'::jsonb, 'wem kräulad mochn'),
  ('de-harfnschbueuelarin-hod-aufn-kraeugoodan-umanaundazupfd-ois-daeds-hendln-rupfn', 'De Harfnschbüülarin hod aufn Kräugoodan umanaundazupfd, ois däds Hendln rupfn!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Die Harfenspielerin hat auf dem Kratzgitter herumgezupft, als täte sie Hühner rupfen!', '[{"kategorie": "wörtlich", "text": "\"Die Harfenistin hat auf dem Kratzgitter herumgezupft, als würde sie Hühner rupfen!\"  2. Die Harfentussi hat die Saiten von ihrem Kratzgitter malträtiert, als würde sie alle rausreißen wollen!  3. So wie die Harfenistin auf den Saiten herumgefingert hat, war das mehr Hendlrupfn als Harfenspiel!"}]'::jsonb, ''),
  ('seine-finga-haum-aufn-kraeugoodan-umanaundaghockd-wia-auf-ana-hiinichn-schreibmaschin', 'Seine Finga haum aufn Kräugoodan umanaundaghockd wia auf ana hiinichn Schreibmaschin!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Seine Finger haben auf dem Kratzgitter herumgehackt wie auf einer hinnigen Schreibmaschine!', '[{"kategorie": "wörtlich", "text": "\"Seine Finger haben auf der Zither herumgehackt wie auf einer kaputten Schreibmaschine!\"  2. Er hat die Zither mit den Fingern malträtiert, als würde er ein Huhn rupfen!  3. Der hat auf der Zither rumgezupft, als würde er ihr die Saiten ausreißen wollen!"}]'::jsonb, ''),
