  ('schwoaza-solo', 'schwoaza Solo', '', '', '', 'Wiener Kartentipplerjargon', 'schwarzer Solo', '[{"kategorie": "wörtlich", "text": "\"schwarzer Solo beim Tarock\" (\"schwarz\" steht für die Spielkartenfarbe \"Tarock\")"}, {"kategorie": "Kartenspielerjargon", "text": "\"schwarzer Solo beim [[Tarock-Zwanzigerrufen]]\", [[Schwarzer]] (ein Spieler [der Rufer] spielt gegen die anderen drei und muss mindestens 45 Punkte erzielen. Die Tarock zählen bei diesem Spiel als Trumpfkarten, d.h. Tarock sticht Farbe)"}]'::jsonb, ''),
  ('i-sog-an-schwoazn-solo-au', 'I sog an schwoazn Solo au!', '', '', '', 'Wiener Kartentipplerjargon', 'Ich sag'' einen schwarzen Solo an!', '[{"kategorie": "wörtlich", "text": "\"Ich sage einen schwarzen Solo an!\"  2. Augen zu und durch – schwarzer Solo ist angesagt!  3. Ich geh ''all in'' - schwarzer Solo!"}]'::jsonb, 'schwoaza Solo'),
  ('a-faabal-is-augsogd', 'A Faabal is augsogd!', '', '', '', 'Wiener Kartentipplerjargon', 'Ein Farbensolo ist angesagt!', '[{"kategorie": "wörtlich", "text": "\"Ich sage einen Farbensolo an!\"  2. Augen zu und durch – Farbensolo ist angesagt!  3. Ich geh ''all in'' - Farbensolo!"}]'::jsonb, ''),
  ('i-bin-umknickd-und-hob-daunn-a-elastische-faschn-kriagd-de-s-gelenk-schdabilisiad-hod', 'I bin umknickd und hob daunn a elastische Faschn kriagd, de s''Gelenk schdabilisiad hod!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Ich bin umgeknickt und hab dann eine elastische Fasche gekriegt, die das Gelenk stabilisiert hat!', '[{"kategorie": "wörtlich", "text": "\"Nach dem Umknicken bekam ich eine elastische Fasche, die das Gelenk stabilisierte!\"  2. Nach dem Umknicken wurde mir ein elastischer Stützverband angelegt, der das Gelenk stützte!  3. Ich bin blöd umgeknickt – dann haben sie mir so ''ne elastische Binde drumgemacht, die den Knöchel stützt!"}]'::jsonb, ''),
  ('wia-haum-a-jeds-fensta-mit-ana-8cm-braadn-faschn-eigfossd', 'Wia haum a jeds Fensta mit ana 8cm braadn Faschn eigfossd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wir haben jedes Fenster wurde mit einer 8 cm breiten Fasche eingefasst!', '[{"kategorie": "wörtlich", "text": "\"Jedes Fenster wurde von uns mit einer 8 cm breiten Fasche umrahmt!\"  2. Wir haben alle Fensteröffnungen mit einem 8 cm breiten Zierrahmen versehen!  3. Jedes Fenster hat von uns eine 8 cm breite weiße Umrandung bekommen!"}]'::jsonb, ''),
  ('de-tia-haengd-schiif-waeu-de-oide-faschn-ausgschloong-is', 'De Tia hängd schiif, wäu de oide Faschn ausgschloong is!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die Tür hängt schief, weil die alte Fasche ausgeschlagen ist!', '[{"kategorie": "wörtlich", "text": "\"Die Tür hängt schief, weil das alte Türband ausgeschlagen ist!\"  2. Das Band ist ausgeleiert, darum kippt die Tür nach unten ab!  3. Das Tragband ist beschädigt, die Tür kann das Gewicht nicht mehr gleichmäßig halten!"}]'::jsonb, ''),
  ('i-bin-umknickd-und-hob-daunn-a-elastische-fatschn-kriagd-de-s-gelenk-schdabilisiad-hod', 'I bin umknickd und hob daunn a elastische Fatschn kriagd, de s''Gelenk schdabilisiad hod!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Ich bin umgeknickt und hab dann eine elastische Fatsche gekriegt, die das Gelenk stabilisiert hat!', '[{"kategorie": "wörtlich", "text": "\"Nach dem Umknicken bekam ich eine elastische Fasche, die das Gelenk stabilisierte!\"  2. Nach dem Umknicken wurde mir ein elastischer Stützverband angelegt, der das Gelenk stützte!  3. Ich bin blöd umgeknickt – dann haben sie mir so ''ne elastische Binde drumgemacht, die den Knöchel stützt!"}]'::jsonb, ''),
  ('wia-haum-a-jeds-fensta-mit-ana-8cm-braadn-fatschn-eigfossd', 'Wia haum a jeds Fensta mit ana 8cm braadn Fatschn eigfossd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wir haben jedes Fenster wurde mit einer 8 cm breiten Fatsche eingefasst!', '[{"kategorie": "wörtlich", "text": "\"Jedes Fenster wurde von uns mit einer 8 cm breiten Fasche umrahmt!\"  2. Wir haben alle Fensteröffnungen mit einem 8 cm breiten Zierrahmen versehen!  3. Jedes Fenster hat von uns eine 8 cm breite weiße Umrandung bekommen!"}]'::jsonb, ''),
  ('de-tia-haengd-schiif-waeu-de-oide-fatschn-ausgschloong-is', 'De Tia hängd schiif, wäu de oide Fatschn ausgschloong is!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die Tür hängt schief, weil die alte Fatsche ausgeschlagen ist!', '[{"kategorie": "wörtlich", "text": "\"Die Tür hängt schief, weil das alte Türband ausgeschlagen ist!\"  2. Das Band ist ausgeleiert, darum kippt die Tür nach unten ab!  3. Das Tragband ist beschädigt, die Tür kann das Gewicht nicht mehr gleichmäßig halten!"}]'::jsonb, ''),
  ('i-woa-no-a-faschnkind-waeu-mei-uarli-gsogd-hod-dass-a-kind-oone-faschn-vawochsd', 'I woa no a Faschnkind - wäu mei Uarli gsogd hod, dass a Kind oone Faschn vawochsd!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Ich war noch ein Faschenkind - weil meine Uroma gesagt hat, dass ein Kind ohne Faschen verwächst!', '[{"kategorie": "wörtlich", "text": "\"Meine Uroma hat mich noch in Faschen eingewickelt, weil sie meinte, Kinder ohne Faschen würden sonst schief wachsen!\"  2. Ich war als Baby von Kopf bis Fuß in Faschen eingewickelt – „sonst kriegt er schiefe Beine“, hat meine Uroma gesagt!  3. Ich war noch ein klassisches Faschenkind – damals dachte man, das verhindert Fehlstellungen!"}]'::jsonb, ''),
  ('de-is-uandlich-faschee', 'De is uandlich faschee!', '', '', '', '', 'Die ist ordentlich faché!', '[{"kategorie": "wörtlich", "text": "\"Die ist gehörig verärgert!\"  2. Die ist mächtig sauer!  3. Die ist richtig wütend!"}]'::jsonb, ''),
  ('si-a-faschee-eihaundln', 'si a Faschee eihaundln', '', '', '', '', 'sich ein Faschee einhandeln', '[{"kategorie": "wörtlich", "text": "\"sich Ärger einhandeln\""}, {"kategorie": "", "text": "Unmut auf sich ziehen"}, {"kategorie": "", "text": "sich eine Portion Zoff abholen"}]'::jsonb, ''),
  ('faschiada-broodn', 'faschiada Broodn', '', '', '', '', 'faschierter Braten', '[{"kategorie": "wörtlich, Deutschland", "text": "\"Hackbraten\" (von [[faschieren]]=\"durch den Fleischwolf drehen\" und \"Braten\"=\"Hackbraten\")"}, {"kategorie": "Gastronomie", "text": "[[falscher Hase]] (Zur Erklärung: Der Hasenbraten war einst ein beliebtes Sonntagsessen. Nach dem Zweiten Weltkrieg nahm die Hasenpopulation aber derart dramatisch ab, dass sich die Leute eine Alternative suchen mussten. So wurde stattdessen [[Faschiertes]] [Hackfleisch] zu einem Braten geformt und in einer Auflaufform in den Ofen gegeben)"}]'::jsonb, ''),
  ('heiliga-leopoid', 'Heiliga Leopoid', '', '', '', '', 'Heiliger Leopold', '[{"kategorie": "wörtlich", "text": "\"Markgraf Leopold III. vom Adelsgeschlecht der Babenberger\" (1073-1136)"}, {"kategorie": "", "text": "Landespatron Österreichs sowie von Wien und Niederösterreich im Besonderen"}, {"kategorie": "", "text": "Gründer des Chorherrenstifts Klosterneuburg nahe Wien (einer Legende zufolge soll bei der Jagd mit seiner Gattin und Freunden auf dem [[Kahlenberg]] der Schleier seiner Frau verweht worden sein. Daraufhin befahl er, den Schleier zu suchen und versprach an seinem Fundort eine Kirche erbauen zu lassen. So soll Klosterneuburg entstanden sein. Auf Bestreben der Habsburger wurde Leopold 1485 heilig gesprochen. Seit 1663 gilt er als Schutzpatron Österreichs und sein Sterbetag, der 15. November, wurde zum Feiertag)"}]'::jsonb, ''),
  ('glei-ramsd-a-fazku-oo', 'Glei ramsd a Fazku oo!', '', '', '', '', 'Gleich räumst du eine Fatzku ab!', '[{"kategorie": "wörtlich", "text": "\"Gleich kassierst du eine Ohrfeige!\"  2. Gleich fängst du dir eine"}, {"kategorie": "", "text": "Gleich gibt''s eine auf die Ohren!"}]'::jsonb, ''),
  ('glei-ramsd-a-faunzn-oo', 'Glei ramsd a Faunzn oo!', '', '', '', '', 'Gleich räumst du eine Faunzen ab!', '[{"kategorie": "wörtlich", "text": "\"Gleich kassierst du eine Ohrfeige!\"  2. Gleich fängst du dir eine"}, {"kategorie": "", "text": "Gleich gibt''s eine auf die Ohren!"}]'::jsonb, ''),
  ('wiidna-hauptschdrossn', 'Wiidna Hauptschdrossn', '', '', '', '', 'Wiedner Hauptstraße', '[{"kategorie": "allg.", "text": "bedeutende Verkehrs- und Geschäftsstraße im 4. Wiener Gemeindebezirk ([[Wieden]])"}, {"kategorie": "", "text": "Die Wiedner Hauptstraße ist eine der ältesten Straßen Wiens und geht auf römische Zeiten zurück, als sie als Verbindung zwischen dem römischen Lager [[Vindobona]] und dem Umland diente. Im Mittelalter entwickelte sich die Straße zu einer wichtigen Handelsroute"}, {"kategorie": "", "text": "Der Name „Wiedner Hauptstraße“ leitet sich vom Bezirk Wieden ab, der nach der ehemaligen Vorstadt Wieden benannt ist"}, {"kategorie": "", "text": "Die Wiedner Hauptstraße ist geprägt von einer Mischung aus historischen Gebäuden, insbesondere aus der Gründerzeit des 19. Jahrhunderts, und modernen Bauten"}, {"kategorie": "", "text": "Die Wiedner Hauptstraße ist heute eine zentrale Lebensader im 4. Wiener Gemeindebezirk Wieden. Sie verbindet historische Bedeutung mit modernem urbanem Leben und bietet eine reiche Mischung aus Handel, Kultur und Gastronomie."}]'::jsonb, ''),
  ('favoritna-fussgaengazone', 'Favoritna Fussgängazone', '', '', '', '', 'Favoritner Fußgängerzone', '[{"kategorie": "allg.", "text": "zentraler und belebter Abschnitt der Favoritenstraße im 10. Wiener Gemeindebezirk ([[Favoriten]])"}, {"kategorie": "", "text": "Sie erstreckt sich vom [[Südtiroler]] Platz, in der Nähe des [[Wiener]] Hauptbahnhofs, bis zum [[Reumannplatz]] und ist eine der wichtigsten Einkaufs- und Flaniermeilen des Bezirks."}]'::jsonb, ''),
  ('wiina-westbaunhof', 'Wiina Westbaunhof', '', '', '', '', 'Wiener Westbahnhof', '[{"kategorie": "allg.", "text": "\"einer der wichtigsten Bahnhöfe in Wien und ein zentraler Verkehrsknotenpunkt im Westen der Stadt\" (kurz auch [[Westbahnhof]] genannt)"}, {"kategorie": "", "text": "Er befindet sich im 15. Wiener Gemeindebezirk ([[Rudolfsheim-Fünfhaus]]) und dient als Endpunkt für mehrere nationale und internationale Bahnstrecken"}, {"kategorie": "", "text": "Der Westbahnhof ist nicht nur ein bedeutender Bahnhof, sondern auch ein Einkaufszentrum und ein historisches Wahrzeichen Wiens"}, {"kategorie": "", "text": "Er wurde ursprünglich 1858 eröffnet und war der Ausgangspunkt der Westbahn, einer der wichtigsten Eisenbahnstrecken Österreichs, die Wien mit Salzburg und weiter mit Deutschland verbindet"}, {"kategorie": "", "text": "Im Zweiten Weltkrieg wurde der Bahnhof schwer beschädigt und in den 1950er Jahren wieder aufgebaut. Das heutige Hauptgebäude im modernen Stil wurde 1951 eröffnet und gilt als ein Beispiel der Nachkriegsarchitektur"}, {"kategorie": "", "text": "Der Bahnhof wurde mehrfach modernisiert, zuletzt im Rahmen des Projekts \"BahnhofCity Wien West\", das 2011 abgeschlossen wurde. Im Zuge dieser Modernisierung wurden die Bahnhofsgebäude umfassend renoviert und mit einem Einkaufszentrum, Gastronomieangeboten und Büros ergänzt."}]'::jsonb, ''),
  ('wiina-hauptbaunhof', 'Wiina Hauptbaunhof', '', '', '', '', 'Wiener Hauptbahnhof', '[{"kategorie": "allg., kurz für", "text": "\"Wiener Hauptbahnhof\" - zentraler Bahnhof in Wien und einer der wichtigsten Verkehrsknotenpunkte in Österreich"}, {"kategorie": "", "text": "Er befindet sich im 10. Wiener Gemeindebezirk ([[Favoriten]]) in unmittelbarer Nähe zum [[Südtiroler]] Platz"}, {"kategorie": "", "text": "Der Wiener Hauptbahnhof wurde zwischen 2010 und 2014 auf dem Gelände des ehemaligen Südbahnhofs errichtet, der 2009 abgerissen wurde. Der Bahnhof verfügt über 12 Bahnsteige, die sowohl für den Fern- als auch für den Nahverkehr genutzt werden, sowie über eine Vielzahl von Geschäften, Restaurants und Serviceeinrichtungen. Die Dachkonstruktion des Bahnhofs ist markant und verleiht dem Gebäude eine einzigartige, futuristische Optik"}, {"kategorie": "", "text": "Der Bau des Hauptbahnhofs war der Ausgangspunkt für die Entwicklung eines neuen Stadtteils, dem [[Quartier]] Belvedere, das moderne Wohn- und Bürogebäude, Hotels, Einkaufszentren und Freizeiteinrichtungen umfasst. Dieses Viertel hat die Umgebung des Bahnhofs in ein lebendiges, urbanes Zentrum verwandelt."}]'::jsonb, ''),
  ('wiina-suedbaunhof', 'Wiina Südbaunhof', '', '', '', '', 'Wiener Südbahnhof', '[{"kategorie": "allg.", "text": "\"historischer Hauptbahnhof in Wien, der als zentraler Verkehrsknotenpunkt für den Süden und Osten Europas diente. Er wurde 1874 eröffnet und war bis zu seinem Abriss im Jahr 2010 in Betrieb\""}, {"kategorie": "", "text": "Der ursprüngliche Wiener Südbahnhof entstand durch den Zusammenschluss zweier Bahnhöfe: des Südbahnhofs und des Ostbahnhofs. Der Südbahnhof wurde ursprünglich als Endstation der Südbahnstrecke nach Triest und Venedig konzipiert, die Wien mit dem Mittelmeer verband. Der Ostbahnhof diente als Ausgangspunkt für Strecken in Richtung Ungarn und die Balkanregion. Diese beiden Bahnhöfe wurden schließlich zu einem großen Bahnhofskomplex zusammengefasst"}, {"kategorie": "", "text": "Nach dem Wiederaufbau in den 1950er Jahren präsentierte sich der Wiener Südbahnhof als modernes Bauwerk der Nachkriegsarchitektur"}, {"kategorie": "", "text": "Das Empfangsgebäude war ein großes, rechteckiges Bauwerk, das durch seine Glas- und Betonarchitektur auffiel. Es bot eine Vielzahl von Dienstleistungen, darunter Restaurants, Geschäfte und Reisebüros, und war ein wichtiger Anlaufpunkt für Reisende in Wien"}, {"kategorie": "", "text": "Der Wiener Südbahnhof wurde 2010 abgerissen, um Platz für den Bau des neuen [[Wiener]] Hauptbahnhofs zu schaffen. Der Hauptbahnhof, der 2014 offiziell eröffnet wurde, ersetzte den Südbahnhof als zentrales Eisenbahndrehkreuz der Stadt. Der neue Hauptbahnhof integriert die Funktionen des Südbahnhofs, des Westbahnhofs und anderer Bahnhöfe und bietet moderne Infrastruktur für den nationalen und internationalen Bahnverkehr."}]'::jsonb, ''),
  ('quatia-belvedea', 'Quatia Belvedea', '', '', '', '', 'Quartier Belvedere', '[{"kategorie": "allg.", "text": "modernes, urbanes Entwicklungsgebiet in Wien, das rund um den [[Wiener]] Hauptbahnhof im 10. Wiener Gemeindebezirk ([[Favoriten]]) entstanden ist"}, {"kategorie": "", "text": "Es umfasst eine Mischung aus Wohn-, Büro-, Hotel- und Geschäftsgebäuden und bildet einen neuen, lebendigen Stadtteil in unmittelbarer Nähe zum historischen [[Schloss]] Belvedere und dem Schlosspark"}, {"kategorie": "", "text": "Das Quartier Belvedere ist Teil eines der größten Stadtentwicklungsprojekte Wiens in den letzten Jahrzehnten. Es wurde als urbanes Zentrum mit hoher Lebensqualität und moderner Architektur konzipiert und zielt darauf ab, Wohnen, Arbeiten und Freizeit auf engem Raum zu vereinen."}]'::jsonb, ''),
  ('oide-favorita', 'Oide Favorita', '', '', '', '', 'Alte Favorita', '[{"kategorie": "wörtlich", "text": "\"Altes Lustschloss Favorita\" (errichtet im [[Augarten]], dem einstigen \"Lustgarten\" der Habsburger, vom lateinischen \"favor\"=\"Gunst\" bzw. \"Gefallen\")"}, {"kategorie": "", "text": "Sommersitz des Hofs im [[Augarten]]"}, {"kategorie": "", "text": "Sitz der [[Wiener]] Sängerknaben"}]'::jsonb, ''),
  ('neiche-favorita', 'Neiche Favorita', '', '', '', '', 'Neue Favorita', '[{"kategorie": "wörtlich", "text": "\"Neues Lustschloss Favorita\" (am Platz des heutigen [[Theresianums]], vom lateinischen \"favor\"=\"Gunst\" bzw. \"Gefallen\")"}, {"kategorie": "hist.", "text": "Sommersitz des Hofs auf der [[Wieden]], der von Kaiser Ferdinand III. begründet wurde"}]'::jsonb, ''),
  ('wiina-saengaknoom', 'Wiina Sängaknoom', '', '', '', '', 'Wiener Sängerknaben', '[{"kategorie": "wörtlich, hist.", "text": "\"Wiener Hofsängerknaben\" (gegründet 1498 durch ein Dekret von Kaiser Maximilian I.)"}, {"kategorie": "heute", "text": "berühmtester Knabenchor der Welt mit Übungs- und Ausbildungsstätte im Wiener [[Augartenpalais]]"}, {"kategorie": "allg.", "text": "Institution des Wiener Musiklebens, bestehend aus insgesamt vier Einzelchören"}]'::jsonb, ''),
  ('maria-teresia', 'Maria Teresia', '', '', '', '', 'Maria Theresia', '[{"kategorie": "wörtlich", "text": "\"Kaiserin Maria Theresia\" (1717-1780, Tochter [[Kaiser]] Karls VI. und seiner Frau Elisabeth Christine von Braunschweig-Wolfenbüttel)"}, {"kategorie": "hist.", "text": "Erzherzogin von Österreich, Königin von Böhmen und Ungarn, seit 1745 - als Gattin von [[Kaiser]] Franz Stephan von Lothringen - Kaiserin des Heiligen Römischen Reiches (ein wesentliches Verdienst der Herrscherin war die Umwandlung der überkommenen feudalen Ländermasse in einen einheitlichen modernen Verwaltungs- und Beamtenstaat mit zentralistischer Staatsverwaltung)"}]'::jsonb, ''),
  ('eazheazog-fraunz-ferdinand', 'Eazheazog Fraunz Ferdinand', '', '', '', '', 'Erzherzog Franz Ferdinand', '[{"kategorie": "wörtlich", "text": "\"Erzherzog Franz Ferdinand von Österreich-Este (1863–1914)\""}, {"kategorie": "", "text": "Er war ein Mitglied des Hauses Habsburg-Lothringen und Thronfolger des österreichisch-ungarischen Kaiserreichs. Er ist vor allem bekannt für seine Ermordung am 28. Juni 1914 in Sarajevo, die als Auslöser für den Ersten Weltkrieg gilt"}, {"kategorie": "", "text": "Franz Ferdinand wurde am 18. Dezember 1863 in Graz geboren. Er war der älteste Sohn von Erzherzog Karl Ludwig, einem Bruder von Kaiser Franz Joseph I., und Maria Annunziata von Neapel-Sizilien. Nach dem Tod seines Vaters im Jahr 1896 wurde Franz Ferdinand der direkte Thronfolger seines Onkels, [[Kaiser]] Franz Joseph I"}, {"kategorie": "", "text": "Franz Ferdinand heiratete 1900 die Gräfin Sophie Chotek, eine Frau von niederem Adel. Da sie nicht dem hohen Adel angehörte, galt die Ehe als morganatisch, was bedeutete, dass ihre Nachkommen vom Thronanspruch ausgeschlossen waren. Trotz dieser Einschränkungen war die Ehe des Paares von tiefer Zuneigung geprägt. Das Paar hatte drei Kinder: Sophie, Maximilian und Ernst"}, {"kategorie": "", "text": "Franz Ferdinand war bekannt für seine konservativen Ansichten und seine Ambitionen, das österreichisch-ungarische Kaiserreich zu reformieren. Er war ein starker Befürworter der Erhaltung der [[Habsburgermonarchie]], sah jedoch die Notwendigkeit, die nationalen Spannungen innerhalb des Vielvölkerstaats zu entschärfen. Er befürwortete eine föderalistische Umgestaltung des Reiches, um den slawischen Völkern innerhalb der Monarchie mehr Autonomie zu gewähren. Diese Pläne stießen jedoch auf Widerstand, insbesondere von ungarischen Nationalisten und Militärs"}, {"kategorie": "", "text": "Am 28. Juni 1914 wurde Franz Ferdinand zusammen mit seiner Frau Sophie in Sarajevo, der Hauptstadt der österreichischen Provinz Bosnien und Herzegowina, von Gavrilo Princip, einem Mitglied der serbisch-nationalistischen Organisation \"Schwarze Hand\", ermordet. Das Attentat von Sarajevo löste eine Kette von Ereignissen aus, die zum Ausbruch des Ersten Weltkriegs führten. Österreich-Ungarn stellte Serbien ein Ultimatum, das zu einer diplomatischen Krise und schließlich zum Krieg zwischen den Großmächten Europas führte"}]'::jsonb, ''),
  ('joseph-ii', 'Joseph II.', '', '', '', '', 'Joseph II.', '[{"kategorie": "wörtlich", "text": "\"Kaiser Joseph II.\" (1741-1790, ältester Sohn von Franz Stephan von Lothringen und dessen Gattin Maria Theresia)"}, {"kategorie": "hist.", "text": "römisch-deutscher König (1764), römisch-deutscher Kaiser (1765-1790), Mitregent seiner Mutter Maria Theresia in den Erbländern (1765-1780), Regent in den Erbländern (1780-1790)"}, {"kategorie": "allg.", "text": "Hauptvertreter des aufgeklärten Absolutismus (realisierte zahlreiche zunkunfsweisende Reformen)"}]'::jsonb, ''),
  ('koarl-vi', 'Koarl VI.', '', '', '', '', 'Karl VI.', '[{"kategorie": "wörtlich", "text": "\"Kaiser Karl VI.\" (1685-1740, zweiter Sohn Leopolds I. und dessen dritter Gattin Eleonore von Pfalz-Neuburg)"}, {"kategorie": "hist.", "text": "von 1711 bis 1740 römisch-deutscher Kaiser und Erzherzog von Österreich sowie Souverän der übrigen habsburgischen Erblande, als Karl III. (ungarisch III. Károly) König von Ungarn und Kroatien, als Karl II. (tschechisch Karel II) König von Böhmen, als Karl III. (spanisch Carlos III) designierter Gegenkönig von Spanien, ab 1713 als Karl VI. (italienisch Carlo VI) König von Neapel sowie durch den Frieden von Utrecht von 1713 bis 1720 als Karl III. (italienisch Carlo III) auch König von Sardinien, und ab 1720 als Karl IV. (italienisch Carlo IV) König von Sizilien"}, {"kategorie": "", "text": "Vater von [[Maria]] Theresia (er erließ die [[Pragmatische]] Sanktion von 1713, die die Unteilbarkeit der Habsburgischen Erblande und die weibliche Erbfolge, zugunsten seiner Tochter Maria Theresia, sicherstellen sollte)"}]'::jsonb, ''),
  ('leopoid-i', 'Leopoid I.', '', '', '', '', 'Leopold I.', '[{"kategorie": "wörtlich", "text": "\"Kaiser Leopold I.\" (1640-1705, Sohn von Ferdinand III. und Maria Anna von Spanien)"}, {"kategorie": "hist.", "text": "Kaiser des Heiligen Römischen Reiches (1658 bis 1705) sowie König in Germanien, Ungarn (ab 1655), Böhmen (ab 1656), Kroatien und Slawonien (ab 1657) (Er führte erfolgreich den Großen Türkenkrieg (1683-1699) gegen das Osmanische Reich, der mit dem Sieg in der Schlacht am Kahlenberg und dem Frieden von Karlowitz endete, wodurch das Habsburgerreich bedeutende Gebiete gewann. Ferner war er war eine zentrale Figur im Spanischen Erbfolgekrieg (1701-1714), der nach seinem Tod weitergeführt wurde und das europäische Machtgleichgewicht neu ordnete)"}, {"kategorie": "", "text": "Vater von [[Karl]] VI."}]'::jsonb, ''),
  ('ferdinand-iii', 'Ferdinand III.', '', '', '', '', 'Ferdinand III.', '[{"kategorie": "wörtlich", "text": "\"Kaiser Ferdinand III.\" (1608-1657, Sohn Ferdinands II. und Maria Annas von Bayern)"}, {"kategorie": "hist.", "text": "Erzherzog von Österreich aus dem Hause Habsburg, römisch-deutscher Kaiser (von 1637 bis zu seinem Tode 1657), König von Ungarn, Kroatien und Böhmen (seit 1625 bzw. 1627) (Er spielte eine entscheidende Rolle bei den Verhandlungen zum Westfälischen Frieden von 1648, der den Dreißigjährigen Krieg beendete und die europäische politische Ordnung neu gestaltete. Ferner bemühte sich Ferdinand III. um Reformen im Heiligen Römischen Reich, um die innere Stabilität und die Macht des Kaisertums zu stärken)"}, {"kategorie": "", "text": "Vater von [[Leopold]] I."}]'::jsonb, ''),
  ('fraunz-joseph-i', 'Fraunz Joseph I.', '', '', '', '', 'Franz Joseph I.', '[{"kategorie": "wörtlich", "text": "\"Kaiser Franz Joseph I.\" (1830-1916, aus dem Haus Habsburg-Lothringen, Sohn des Erzherzogs Franz Karl und der bayerischen Prinzessin Sophie)"}, {"kategorie": "hist.", "text": "Kaiser von Österreich sowie Apostolischer König von Ungarn und König von Böhmen (von 1848 bis zu seinem Tode, wobei er mit seiner Regierungszeit von nahezu 68 Jahren alle anderen Herrscher seiner Dynastie deutlich übertraf) (1867 initiierte er den Österreichisch-Ungarischen Ausgleich, der die Doppelmonarchie Österreich-Ungarn schuf und den inneren Frieden im Reich förderte. Zudem wurden unter seiner Herrschaft zahlreiche Modernisierungen und Reformen durchgeführt, darunter der Ausbau der Infrastruktur und die Einführung von Verfassungsreformen)"}, {"kategorie": "", "text": "Vater von [[Kronprinz]] Rudolf"}]'::jsonb, ''),
  ('kronprinz-rudolf', 'Kronprinz Rudolf', '', '', '', '', 'Kronprinz Rudolf', '[{"kategorie": "wörtlich", "text": "\"Kronprinz Rudolf von Österreich und Ungarn\" (1858-1889, einziger Sohn von Kaiser Franz Joseph I. und Kaiserin Elisabeth)"}, {"kategorie": "hist.", "text": "Kronprinz des kaiserlichen Österreich (Cisleithanien) und des königlichen Ungarn. Wie alle habsburgischen Prinzen trug er, den Hausgesetzen des Hauses Habsburg-Lothringen entsprechend, den Titel Erzherzog (ungarisch főherceg)"}, {"kategorie": "", "text": "Geliebter von [[Mary]] Vetsera (Kronprinz Rudolf starb 1889 auf tragische Weise durch einen erweiterten Suizid zusammen mit seiner Geliebten Mary Vetsera im Schloss Mayerling. Dieser Vorfall, bekannt als der Mayerling-Vorfall, erschütterte das Habsburgerreich und hatte tiefgreifende Auswirkungen auf die kaiserliche Familie)"}]'::jsonb, ''),
  ('koarl-i', 'Koarl I.', '', '', '', '', 'Karl I.', '[{"kategorie": "wörtlich", "text": "\"Kaiser Karl I.\" (1887-1922, entstammt der Dynastie Habsburg-Lothringen, Sohn von Erzherzog Otto und dessen Ehefrau Maria Josepha von Sachsen)"}, {"kategorie": "hist.", "text": "\"letzter Kaiser von Österreich\" (von 1916 bis zu seinem Verzicht auf „jeden Anteil an den Staatsgeschäften“ 1918), sowie Apostolischer König von Ungarn (als Karl IV. bzw. ungarisch \"IV. Károly\")"}, {"kategorie": "", "text": "Großneffe Kaiser Franz Josephs I. (Karl I. bemühte sich vergeblich um einen Separatfrieden mit den Alliierten, um das Ende des Ersten Weltkriegs herbeizuführen. Nach dem Zerfall Österreich-Ungarns 1918 dankte er ab und ging ins Exil, zunächst in die Schweiz und später nach Madeira, wo er 1922 in Funchal starb)"}]'::jsonb, ''),
  ('koarl-ii', 'Koarl II.', '', '', '', '', 'Karl II.', '[{"kategorie": "allg.", "text": "\"letzter Habsburger König von Spanien, auch bekannt als Carlos II. von Spanien (6. November 1661 – 1. November 1700)\""}, {"kategorie": "", "text": "Er regierte von 1665 bis zu seinem Tod im Jahr 1700. Seine Regierungszeit war geprägt von innenpolitischen Schwierigkeiten, wirtschaftlichem Niedergang und außenpolitischen Herausforderungen, die schließlich zum Ausbruch des Spanischen Erbfolgekrieges führten"}, {"kategorie": "", "text": "Karl II. wurde als Sohn von Philipp IV. von Spanien und Maria Anna von Österreich geboren. Er war das letzte überlebende Kind seiner Eltern, die viele ihrer Nachkommen durch Krankheiten verloren hatten"}, {"kategorie": "", "text": "Karl war von Geburt an gesundheitlich stark beeinträchtigt, was auf die jahrhundertelange Inzucht in der spanischen Linie der Habsburger zurückzuführen ist. Er litt unter körperlichen und geistigen Schwächen, was seine Fähigkeit, effektiv zu regieren, erheblich einschränkte"}, {"kategorie": "", "text": "Karl II. bestieg den spanischen Thron im Jahr 1665 nach dem Tod seines Vaters, Philipp IV., obwohl er erst vier Jahre alt war. Seine Mutter, Maria Anna von Österreich, übernahm die Regentschaft während seiner Minderjährigkeit"}, {"kategorie": "", "text": "Karl hinterließ keine Erben, und seine Nachfolge führte direkt zum Ausbruch des Spanischen Erbfolgekrieges, der die politischen Landkarten Europas nachhaltig veränderte. Sein Tod markierte das Ende der spanischen Habsburger und den Beginn einer neuen Ära in der europäischen Geschichte."}]'::jsonb, ''),
  ('mary-vetsera', 'Mary Vetsera', '', '', '', '', 'Mary Vetsera', '[{"kategorie": "wörtlich", "text": "\"Marie Alexandrine Freiin von Vetsera\" (1871-1889, Tochter des Diplomaten Albin Ritter von Vetsera, der 1870 in den [[Freiherrenstand]] erhoben wurde, sowie von Helene (geborene Baltazzi), welche aus einer der reichsten griechischen Familien jener Zeit stammte)"}, {"kategorie": "", "text": "Geliebte von [[Kronprinz]] Rudolf (Mary Vetsera hatte eine romantische Beziehung mit dem Kronprinzen, die in den konservativen Kreisen der [[Habsburgermonarchie]] skandalös war. Am 30. Januar 1889 starb sie zusammen mit Kronprinz Rudolf im Schloss Mayerling durch einen erweiterten Suizid. Der Vorfall, bekannt als der Mayerling-Vorfall, war ein großer Skandal und erschütterte Europa. Mary Vetsera wurde nur 17 Jahre alt und bleibt eine tragische Figur der Habsburgergeschichte)"}]'::jsonb, ''),
  ('pragmatische-sanktion', 'Pragmatische Sanktion', '', '', '', '', 'Pragmatische Sanktion', '[{"kategorie": "wörtlich", "text": "\"Pragmatische Sanktion\" (Dekret [[Kaiser]] Karls VI. von 1713, das die Unteilbarkeit der Habsburgischen Erblande festlegte und die weibliche Thronfolge ermöglichte)"}, {"kategorie": "", "text": "\"Kaiserliche Urkunde\" bzw. \"Hausgesetz\" (mit welchem [[Karl]] VI. die Unteilbarkeit und Untrennbarkeit aller habsburgischen Erbkönigreiche und Länder festlegte und zu diesem Zweck eine einheitliche Erbfolgeordnung vorsah, dank welcher seine Tochter Maria Theresia die Thronfolge in den habsburgischen Ländern antreten konnte)"}]'::jsonb, ''),
  ('prinz-eugen', 'Prinz Eugen', '', '', '', '', 'Prinz Eugen', '[{"kategorie": "wörtlich", "text": "\"Prinz Franz Eugen von Savoyen-Carignan\" (1663-1736, entstammt einer Nebenlinie des in Italien souverän herrschenden Hauses Savoyen)"}, {"kategorie": "hist.", "text": "bedeutendster Feldherr der [[Habsburgermonarchie]] (ab 1697 Oberbefehlshaber im Großen Türkenkrieg, Oberkommandierender der antifranzösischen Haager Großen Allianz während des Spanischen Erbfolgekrieges (1701–1714), Präsident des Hofkriegsrats, Diplomat und Inhaber weiterer hoher Staatsämter. Im Venezianisch-Österreichischen Türkenkrieg (1714–1718) sicherte er die österreichische Vorherrschaft in Südosteuropa)"}, {"kategorie": "", "text": "Erbauer des Schlosses [[Belvedere]] (ursprünglich Sommerresidenz, diente das Schloss, bestehend aus dem Oberen und Unteren Belvedere, dem Prinzen Eugen von Savoyen in der Folge nicht nur als Wohnsitz, sondern auch zur Repräsentation seiner militärischen Erfolge und seines kulturellen Mäzenatentums)"}]'::jsonb, ''),
  ('schloss-belvedea', 'Schloss Belvedea', '', '', '', '', 'Schloss Belvedere', '[{"kategorie": "wörtlich", "text": "\"Schloss Belvedere\" (vom italienischen \"bel vedere\"=\"schöne Aussicht\")"}, {"kategorie": "", "text": "Bedeutendes Kunstmuseum und ein herausragendes Beispiel barocker Architektur (erbaut von Johann Lucas von Hildebrandt (1668–1745) zwischen 1714 und 1723 für [[Prinz]] Eugen von Savoyen. Das Obere Belvedere und das Untere Belvedere - benannt aufgrund der Lage auf einem südlich der damaligen Stadt ansteigenden Hang - bilden mit der verbindenden Gartenanlage ein barockes Ensemble. Die beiden Schlossbauten beherbergen heute die Sammlungen des Belvederes (Österreichische Galerie Belvedere) und Räumlichkeiten für Wechselausstellungen)"}, {"kategorie": "", "text": "Ort der Unterzeichnung des [[Österreichischen]] Staatsvertrags (welcher im \"Oberen Belvedere\" am 15. Mai 1955 unterzeichnet wurde)"}]'::jsonb, ''),
  ('oestarreichischa-schdootsvatrog', 'Östarreichischa Schdootsvatrog', '', '', '', '', 'Österreichischer Staatsvertrag', '[{"kategorie": "allg.", "text": "\"internationaler Vertrag, der am 15. Mai 1955 in Wien im [[Schloss]] Belvedere unterzeichnet wurde und die zehnjährige [[Besatzungszeit]] Österreichs nach dem [[Zweiten]] Weltkrieg beendete\""}, {"kategorie": "", "text": "Die Unterzeichner waren die vier Besatzungsmächte (USA, Sowjetunion, Großbritannien und Frankreich) sowie die österreichische Regierung"}, {"kategorie": "", "text": "Der Vertrag stellte die volle Souveränität Österreichs wieder her und sah den Abzug aller ausländischen Truppen vor"}, {"kategorie": "", "text": "Gleichzeitig verpflichtete sich Österreich zur [[immerwährenden]] Neutralität, was bedeutete, dass es keine militärischen Bündnisse eingehen oder ausländische Militärbasen auf seinem Territorium zulassen würde"}, {"kategorie": "", "text": "Der Staatsvertrag war ein entscheidendes Dokument in der Nachkriegsordnung Europas und trug wesentlich dazu bei, Österreichs Position als neutraler Staat und Brücke zwischen Ost und West während des Kalten Krieges zu festigen."}]'::jsonb, ''),
  ('immawearende-neutralitaet', 'immawearende Neutralität', '', '', '', '', 'immerwährende Neutralität', '[{"kategorie": "", "text": "\"üblicher Begriff des Völkerrechts, der die Bündnisfreiheit eines Landes festlegt\""}, {"kategorie": "", "text": "Grundsatz der österreichischen Außenpolitik, festgelegt im [[österreichischen]] Staatsvertrag von 1955 und in der österreichischen Verfassung verankert (verpflichtet Österreich, militärisch neutral zu bleiben, keine militärischen Bündnisse einzugehen und keine fremden Militärbasen auf seinem Territorium zuzulassen)"}]'::jsonb, ''),
  ('oide-faeae', 'oide Fää', '', '', '', '', 'alte Fee', '[{"kategorie": "", "text": "\"alte Vogelscheuche\""}, {"kategorie": "", "text": "\"alte [[Grammel]]\""}, {"kategorie": "", "text": "altes, boshaftes Weib"}]'::jsonb, ''),
  ('des-is-wos-fia-feinspitze', 'Des is wos fia Feinspitze!', '', '', '', '', 'Das ist etwas für Feinspitze!', '[{"kategorie": "", "text": "Das ist etwas für Feinschmecker!  2. Das ist etwas für Genießer!"}]'::jsonb, ''),
  ('auf-an-foeoesn-in-da-wachau-haums-des-greessde-haeaefn-von-oestarreich-hibaud', 'Auf an Föösn in da Wachau haums des greessde Hääfn von Östarreich hibaud!', '', '', '', 'Wiener Gaunersprache', 'Auf einen Felsen in der Wachau haben sie das größte Gefängnis von Österreich hingebaut!', '[{"kategorie": "wörtlich", "text": "\"Auf einem Felsen über der Wachau steht das größte Gefängnis Österreichs!\"  2. Oben in der Wachau thront das größte Gefängnis des Landes auf einem steilen Felsen!  3. Über der Wachau steht auf einem Felsrücken das größte Gefängnis Österreichs!"}]'::jsonb, ''),
  ('des-goeoed-liigt-auf-da-fenstabaunk', 'Des Gööd liigt auf da Fenstabaunk!', '', '', '', '', 'Das Geld liegt auf der Fensterbank!', '[{"kategorie": "wörtlich", "text": "\"Das Geld liegt auf dem Fensterbrett!\" (in Anspielung darauf, dass man den [[Hübschlerinnen]] das Geld für ihre Liebesdienste stets im Voraus auf die Fensterbank legen musste)"}, {"kategorie": "fig.", "text": "\"Das Geld im Fenster lockt ganz nah!\"  3. Das Geld im Fenster ist näher als man glaubt!  (in Anspielung darauf, dass die Fensterbank der wohl unsicherste Aufbewahrungsort für Geld ist und das Geld dort sehr schnell Beine bekommen wird)"}, {"kategorie": "Kartenspielerjargon, wörtlich", "text": "\"Geld im Fenster\" (vom ungarischen Tarockspruch \"pénz az ablakban\"=\"Geld im Fenster\"), \"Nullnummer\", \"Spiel mit Nullergebnis\", \"Nullsummenspiel\" (Kartenrunde, bei der sich Gewinne und Verluste wechselseitig egalisieren)"}]'::jsonb, ''),
